Implement brute-force exact nearest neighbor search over the vector index. Uses SIMD dot product + binary heap for efficient top-k retrieval.

pub fn search_top_k(
    index: &VectorIndex,
    query: &[f32],     // L2-normalized query embedding
    k: usize,
    filter: Option<&dyn Fn(usize) -> bool>,  // Optional per-record filter
) -> Vec<VectorHit> {
    // Use BinaryHeap<Reverse<VectorHit>> for min-heap (tracks worst of top-k)
    // For each record in index:
    //   1. Optional filter check (skip if filtered)
    //   2. Compute dot_product_f16_f32(stored, query)
    //   3. If score > heap.peek() or heap.len() < k: push to heap
    // Return sorted Vec<VectorHit> (descending by score)
}

