pub fn build_schema() -> Schema {
    let mut builder = Schema::builder();

    // Required fields (all documents must have these)
    builder.add_text_field('id', STRING | STORED);           // Unique document ID
    builder.add_text_field('content', TEXT | STORED);         // Main searchable text
    builder.add_i64_field('created_at', INDEXED | STORED | FAST);  // Timestamp for sorting

