Implement the score blending algorithm that combines fast-tier and quality-tier semantic scores when the quality model finishes processing.

pub fn blend_two_tier(
    fast_results: &[VectorHit],      // From fast embedder (already normalized)
    quality_results: &[VectorHit],   // From quality embedder (already normalized)
    blend_factor: f32,               // 0.0 = fast-only, 1.0 = quality-only
) -> Vec<VectorHit> {
    // For each document appearing in either result set:
    // blended_score = fast_score * (1.0 - blend_factor) + quality_score * blend_factor
    //
    // Default blend_factor: 0.7 (70% quality, 30% fast)
    //
    // Algorithm:
    // 1. Normalize both sets to [0, 1] via min_max_normalize
