Implement the TwoTierSearcher — the main orchestrator that ties everything together into the progressive search experience. This is the crown jewel of frankensearch.

pub struct TwoTierSearcher<'a> {
    index: &'a TwoTierIndex,
    fast_embedder: Arc<dyn Embedder>,
    quality_embedder: Option<Arc<dyn Embedder>>,
    lexical_index: Option<&'a LexicalSearch>,
    reranker: Option<&'a dyn Reranker>,
    config: TwoTierConfig,
}

impl<'a> TwoTierSearcher<'a> {
    pub fn new(
        index: &'a TwoTierIndex,
        embedder_stack: &EmbedderStack,
        config: TwoTierConfig,
    ) -> Self;

    /// Set optional lexical index for hybrid search
    pub fn with_lexical(self, index: &'a LexicalSearch) -> Self;

    /// Set optional reranker
    pub fn with_reranker(self, reranker: &'a dyn Reranker) -> Self;

    /// Execute progressive search, yielding phases as an iterator.
    /// 
    /// Usage:
    ///   for phase in searcher.search('my query', 10) {
    ///       match phase {
    ///           SearchPhase::Initial { results, latency_ms } => {
    ///               // Display fast results immediately (~15ms)
    ///           }
    ///           SearchPhase::Refined { results, latency_ms } => {
    ///               // Update display with refined rankings (~160ms)
    ///           }
    ///           SearchPhase::RefinementFailed { error } => {
    ///               // Keep showing initial results
    ///           }
    ///       }
    ///   }
    pub fn search(&self, query: &str, k: usize) -> TwoTierSearchIter<'_>;
}

Iterator implementation:

struct TwoTierSearchIter<'a> {
    searcher: &'a TwoTierSearcher<'a>,
    query: String,
    k: usize,
    phase: u8,              // 0 = fast, 1 = quality, 2 = done
    fast_results: Option<Vec<VectorHit>>,
    lexical_results: Option<Vec<LexicalHit>>,
}

impl Iterator for TwoTierSearchIter<'_> {
    type Item = SearchPhase;

    fn next(&mut self) -> Option<SearchPhase> {
        match self.phase {
            0 => {
                // Phase 0: Fast tier
                let start = Instant::now();

                // 1. Embed query with fast model (~1ms)
                let query_vec = self.searcher.fast_embedder.embed(&self.query)?;

                // 2. Search fast index (~10ms)
                let candidates = candidate_count(self.k, 0);
                let fast_hits = self.searcher.index.search_fast(&query_vec, candidates);

                // 3. Optional: lexical search in parallel (if available)
                let lexical_hits = self.searcher.lexical_index.map(|li| li.search(&self.query, candidates));

                // 4. Fuse results
                let results = if let Some(lh) = &lexical_hits {
                    rrf_fuse(lh, &fast_hits, self.k, 0, &self.searcher.config.rrf_config())
                } else {
                    fast_hits.into_scored_results()
                };

                self.fast_results = Some(fast_hits);
                self.lexical_results = lexical_hits;
                self.phase = if self.searcher.quality_embedder.is_some() && !self.searcher.config.fast_only { 1 } else { 2 };

                Some(SearchPhase::Initial { results, latency_ms: start.elapsed().as_millis() as u64 })
            }
            1 => {
                // Phase 1: Quality refinement
                let start = Instant::now();

                let quality_embedder = self.searcher.quality_embedder.as_ref().unwrap();

                // 1. Embed query with quality model (~128ms)
                let query_vec = match quality_embedder.embed(&self.query) {
                    Ok(v) => v,
                    Err(e) => {
                        self.phase = 2;
                        return Some(SearchPhase::RefinementFailed { error: e });
                    }
                };

                // 2. Get quality scores for top candidates
                let fast = self.fast_results.as_ref().unwrap();
                let max_refine = self.searcher.config.max_refinement_docs.min(fast.len());
                let candidate_indices: Vec<usize> = fast[..max_refine].iter().map(|h| h.index).collect();
                let quality_scores = self.searcher.index.quality_scores_for_indices(&query_vec, &candidate_indices);

                // 3. Blend fast + quality scores
                let blended = blend_scored(fast, &quality_scores, self.searcher.config.quality_weight, max_refine);

                // 4. Re-fuse with lexical if available
                let results = if let Some(lh) = &self.lexical_results {
                    rrf_fuse(lh, &blended, self.k, 0, &self.searcher.config.rrf_config())
                } else {
                    blended.into_scored_results()
                };

                // 5. Optional reranking
                // (if reranker available, rerank top results)

                self.phase = 2;
                Some(SearchPhase::Refined { results, latency_ms: start.elapsed().as_millis() as u64 })
            }
            _ => None,
        }
    }
}

This is the most complex component. The key insight is that the iterator pattern allows callers to process fast results IMMEDIATELY while the quality refinement continues. A TUI can display initial results and then smoothly update when refinement completes. An API can return fast results first and stream refinements via SSE.

Performance budget:
- Phase 0 (Initial): < 15ms total
- Phase 1 (Refined): < 200ms total

