    /// Run the refresh loop as an asupersync task. Returns when cancelled via Cx.
    pub async fn run(&self, cx: &Cx) -> Outcome<(), SearchError> {
        loop {
            self.run_cycle().await?;
            cx.sleep(self.config.refresh_interval).await;
            if cx.is_cancel_requested() { return Ok(()); }
        }
    }
}

