pub struct RefreshWorker {
    receiver: asupersync::channel::mpsc::Receiver<EmbeddingJob>,
    index_writer: Arc<asupersync::sync::Mutex<VectorIndexWriter>>,
    poll_interval: Duration,
    batch_size: usize,
}

impl RefreshWorker {
    /// Run the worker within an asupersync region.
    /// The region guarantees: no orphan tasks, clean shutdown on cancel.
    pub async fn run(&self, cx: &Cx) -> asupersync::Outcome<(), SearchError> {
        loop {
            // Cancel-aware sleep (returns Cancelled if shutdown requested)
            cx.sleep(self.poll_interval).await;
            cx.checkpoint()?;  // Early exit point on cancellation

            // Drain available jobs (non-blocking)
            let batch = self.drain_batch(cx).await;
            if batch.is_empty() { continue; }

            // Process batch with budget enforcement
            let budget = Budget {
                deadline: Some(cx.now() + Duration::from_secs(30)),
                poll_quota: 10_000,
                ..Default::default()
