Define the core Embedder trait in frankensearch-core. This is the central abstraction that all embedding models implement. Must be object-safe (dyn Embedder) for runtime polymorphism.

Trait design (synthesized from all 3 codebases):

pub trait Embedder: Send + Sync {
    /// Generate embedding for a single text.
    fn embed(&self, text: &str) -> SearchResult<Vec<f32>>;

    /// Batch embedding for multiple texts (default: sequential).
    fn embed_batch(&self, texts: &[&str]) -> SearchResult<Vec<Vec<f32>>> {
        texts.iter().map(|t| self.embed(t)).collect()
    }

    /// Embedding dimension (e.g., 256 for potion, 384 for MiniLM).
    fn dimension(&self) -> usize;

    /// Unique identifier string (e.g., 'minilm-384', 'fnv1a-384').
    fn id(&self) -> &str;

    /// Human-readable model name.
    fn model_name(&self) -> &str;

    /// Whether this produces semantically meaningful embeddings.
    /// Hash embedders return false; ML models return true.
    fn is_semantic(&self) -> bool;

    /// Performance category for tiering decisions.
    fn category(&self) -> ModelCategory;

    /// Whether this model supports Matryoshka Representation Learning (dim truncation).
    fn supports_mrl(&self) -> bool { false }

    /// Truncate embedding to target dimension (only valid if supports_mrl()).
    fn truncate_embedding(&self, embedding: &[f32], target_dim: usize) -> SearchResult<Vec<f32>> {
        if target_dim >= embedding.len() { return Ok(embedding.to_vec()); }
        Ok(l2_normalize(&embedding[..target_dim]))
    }
}

Supporting types:

pub enum ModelCategory {
    /// Hash-based (FNV-1a): ~0.07ms, no semantic meaning
    HashEmbedder,
    /// Static token embeddings (Model2Vec/potion): ~0.5-1ms, decent semantics
    StaticEmbedder,
    /// Transformer inference (MiniLM, BGE): ~100-500ms, best quality
    TransformerEmbedder,
}

pub enum ModelTier {
    /// Ultra-fast for immediate results (hash or static embedder)
    Fast,
    /// High-quality for refinement (transformer embedder)
    Quality,
}

pub struct ModelInfo {
    pub id: String,
    pub name: String,
    pub dimension: usize,
