Define the core result types that flow through the entire search pipeline. These need to be generic enough to work with any document type (tweets, agent sessions, mail messages) while carrying enough scoring metadata for fusion and display.

/// A scored search result from any search phase.
pub struct ScoredResult {
    /// Opaque document identifier (caller-defined).
    pub doc_id: String,
    /// Primary relevance score (normalized 0.0-1.0 after fusion).
    pub score: f32,
    /// Optional reranker score (set by rerank step).
    pub rerank_score: Option<f32>,
    /// Which sources contributed to this result.
    pub sources: SourceContribution,
    /// Arbitrary metadata (caller can attach doc-specific data).
    pub metadata: Option<serde_json::Value>,
}

/// A raw hit from vector similarity search.
pub struct VectorHit {
    /// Index into the vector store.
    pub index: usize,
    /// Cosine similarity score (raw, not normalized).
    pub score: f32,
    /// Document identifier.
    pub doc_id: String,
}

/// A hit from hybrid fusion (lexical + semantic combined).
pub struct FusedHit {
    /// Document identifier.
    pub doc_id: String,
    /// RRF-fused score.
    pub rrf_score: f64,
    /// Individual source scores for debugging/display.
    pub lexical_rank: Option<usize>,
    pub semantic_rank: Option<usize>,
    pub lexical_score: Option<f32>,
    pub semantic_score: Option<f32>,
}

/// Tracks which retrieval sources contributed to a result.
pub struct SourceContribution {
    pub lexical: bool,
    pub semantic_fast: bool,
    pub semantic_quality: bool,
    pub reranked: bool,
}

/// Search mode selector.
pub enum SearchMode {
    Lexical,    // BM25 keyword matching only
    Semantic,   // Embedding similarity only
    Hybrid,     // RRF fusion of lexical + semantic
    TwoTier,    // Progressive: fast semantic → quality refinement + lexical fusion
}

/// Progressive search phases for two-tier display.
pub enum SearchPhase {
    /// Initial results from fast tier (displayed immediately).
    Initial {
        results: Vec<ScoredResult>,
        latency_ms: u64,
    },
    /// Refined results after quality tier completes.
    Refined {
        results: Vec<ScoredResult>,
        latency_ms: u64,
    },
    /// Quality refinement failed; initial results remain valid.
    RefinementFailed {
        error: SearchError,
    },
}

All types should derive: Debug, Clone, Serialize, Deserialize (where appropriate).

