REVISION (review pass - FrankenSQLite API verification):

1. SQL PARAMETER BINDING: All queries must use SqliteValue enum for parameters:
   conn.execute_with_params(
       "INSERT INTO documents (doc_id, source_path, content_preview, content_hash, content_length, created_at, updated_at, metadata_json) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
       &[
           SqliteValue::Text(doc.doc_id.clone()),
           doc.source_path.as_ref().map_or(SqliteValue::Null, |s| SqliteValue::Text(s.clone())),
           SqliteValue::Text(doc.content_preview.clone()),
           SqliteValue::Blob(doc.content_hash.to_vec()),
           SqliteValue::Integer(doc.content_length as i64),
           SqliteValue::Integer(doc.created_at),
           SqliteValue::Integer(doc.updated_at),
           doc.metadata.as_ref().map_or(SqliteValue::Null, |v| SqliteValue::Text(serde_json::to_string(v).unwrap())),
       ]
   )?;

2. ROW EXTRACTION HELPERS: Since Row::get() returns Option<&SqliteValue>, add typed extraction:
   fn get_text(row: &Row, idx: usize) -> SearchResult<String> {
       match row.get(idx) {
           Some(SqliteValue::Text(s)) => Ok(s.clone()),
           Some(SqliteValue::Null) => Err(SearchError::StorageError("unexpected NULL".into())),
           _ => Err(SearchError::StorageError("type mismatch".into())),
       }
   }
   fn get_optional_text(row: &Row, idx: usize) -> SearchResult<Option<String>> { ... }
   fn get_i64(row: &Row, idx: usize) -> SearchResult<i64> { ... }
   fn get_blob(row: &Row, idx: usize) -> SearchResult<Vec<u8>> { ... }

3. TRANSACTION WRAPPING: upsert_batch() should use the Storage::transaction() helper from the bd-3w1.1 revision. Each batch is atomic:
   storage.transaction(|conn| {
       for doc in docs {
           // upsert logic
       }
       Ok(batch_result)
   })?;

4. CONTENT_HASH AS BLOB: The schema correctly uses BLOB for content_hash (32 bytes). When querying:
   conn.query_with_params("SELECT * FROM documents WHERE content_hash = ?",
       &[SqliteValue::Blob(hash.to_vec())])?;

