      pub visibility_timeout_ms: u64,         // Default: 30_000 (30s)
      pub max_retries: u32,                   // Default: 3
      pub retry_base_delay_ms: u64,           // Default: 100
      pub stale_job_threshold_ms: u64,        // Default: 300_000 (5min)
      pub backpressure_threshold: usize,      // Default: 10_000 pending jobs
  }

  pub struct JobQueueMetrics {
