      pub total_completed: AtomicU64,
      pub total_failed: AtomicU64,
      pub total_skipped: AtomicU64,
      pub total_retried: AtomicU64,
      pub total_deduplicated: AtomicU64,
      pub total_batches_processed: AtomicU64,
      pub total_embed_time_us: AtomicU64,
  }

  impl PersistentJobQueue {
      /// Enqueue a document for embedding. Deduplicates by (doc_id, embedder_id).
      /// If a pending job exists with same content_hash, returns Ok(false) (skipped).
      /// If a pending job exists with different content_hash, replaces it.
      pub fn enqueue(&self, doc_id: &str, embedder_id: &str, content_hash: &[u8; 32], priority: i32) -> SearchResult<bool>;

      /// Enqueue a batch atomically (single transaction)
      pub fn enqueue_batch(&self, jobs: &[EnqueueRequest]) -> SearchResult<BatchEnqueueResult>;

