      /// Jobs processing for > visibility_timeout_ms get reset to 'pending'
      pub fn reclaim_stale_jobs(&self) -> SearchResult<usize>;

      /// Check backpressure (returns true if queue depth exceeds threshold)
      pub fn is_backpressured(&self) -> SearchResult<bool>;

